{{if $.user}}<label for="name">{{$.t.name}}</label><input id="name" name="name" value="{{$.custName}}" required autocomplete="name">
<label for="phone">{{$.t.phone}}</label><input id="phone" name="phone" type="tel" value="{{$.custPhone}}" placeholder="+9715xxxxxxxx" required autocomplete="tel">
{{template "payment" $}}
<p><button id="go" disabled>{{$.t.confirm_booking}}</button></p>
