<script>
(function(){var p=document.getElementById('picker'),box=document.getElementById('slots'),d=document.getElementById('date'),s=document.getElementById('staff'),t=document.getElementById('time'),go=document.getElementById('go');
function load(){t.value='';if(go)go.disabled=true;box.textContent=box.dataset.loading;
fetch('/api/slots?service='+p.dataset.service+'&staff='+encodeURIComponent(s.value)+'&date='+encodeURIComponent(d.value)).then(function(r){return r.json()}).then(function(j){
box.textContent='';if(!j.slots||!j.slots.length){box.textContent=box.dataset.none;return}
j.slots.forEach(function(x){var b=document.createElement('button');b.type='button';b.className='slot';b.textContent=x.time;
b.onclick=function(){t.value=x.time;[].forEach.call(box.children,function(c){c.classList.remove('on')});b.classList.add('on');if(go)go.disabled=false};box.appendChild(b)})
}).catch(function(){box.textContent=box.dataset.none})}
d.onchange=load;s.onchange=load;load()})();
</script>{{end}}{{template "bottom" .}}

