scripts.pay_again:
// POST /bookings/:id/pay (signed in): pay a booking that is still waiting for its card payment
function handle(req) {
  const lang = req.form.lang === 'ar' ? 'ar' : 'en', q = lang === 'ar' ? '&lang=ar' : '';
  const id = Number(req.params.id);
  const o = db.query('SELECT * FROM bookings WHERE id = ? AND user_id = ?', id, req.user.id)[0];
  if (!o) return {template: 'not_found', data: page(req, {}), status: 404};
  if (o.status !== 'pending' || o.payment_method !== 'card') return {redirect: '/bookings/' + id + (lang === 'ar' ? '?lang=ar' : '')};
  // The hold lasts an hour; after that the time or seat may have gone to someone else.
  let free = false;
  if (o.kind === 'class') {
    const c = db.query('SELECT * FROM classes WHERE id = ? AND active = 1', o.class_id)[0];
    free = !!c && (seatsTaken(id)[c.id] || 0) < c.capacity;
  } else {
    const s = db.query('SELECT * FROM services WHERE id = ?', o.service_id)[0];
    free = !!s && freeSlots(business(), s, o.staff_id, o.date, id).some(x => x.time === o.time);
  }
  if (!free) {
    db.exec("UPDATE bookings SET status = 'expired' WHERE id = ?", id);
    return {redirect: '/bookings/' + id + '?error=error_slot' + q};
  }
  return proceed(req, id, lang);
}

scripts.cancel:
// POST /bookings/:id/cancel (signed in): the customer cancels, until business.cancellation_hours before the start.
// What was paid by card (the deposit or the full price) is refunded at once; if the refund fails, the owner is asked to.
function handle(req) {
  const lang = req.form.lang === 'ar' ? 'ar' : 'en', q = lang === 'ar' ? '&lang=ar' : '';
  const id = Number(req.params.id);
  const o = db.query('SELECT * FROM bookings WHERE id = ? AND user_id = ?', id, req.user.id)[0];
  if (!o) return {template: 'not_found', data: page(req, {}), status: 404};
  if (!canCancel(business(), o)) return {redirect: '/bookings/' + id + '?error=error_cancel' + q};
  db.exec("UPDATE bookings SET status = 'cancelled' WHERE id = ? AND user_id = ?", id, req.user.id);
  if (o.status === 'confirmed') {
    const refunded = refundBooking(o, 'requested_by_customer');
    const now = db.query('SELECT * FROM bookings WHERE id = ?', id)[0];
    mail(now, req.origin, 'cancelled');
    tellOwner(now, 'Cancelled by customer', refunded > 0 ? 'AED ' + money(refunded) + ' was refunded to the card automatically.'
      : refunded < 0 ? 'AED ' + money(o.paid_amount) + ' was paid by card and the automatic refund failed. Refund it on the Payments page or in Stripe.' : '');
  }
  return {redirect: '/bookings/' + id + (lang === 'ar' ? '?lang=ar' : '')};
}

